<script setup lang="ts">
import {computed} from 'vue'
import type {ScanConfig,Policy,Proxy,CredentialSet} from '../types'
const props=withDefaults(defineProps<{modelValue:ScanConfig;policy:Policy;proxies?:Proxy[];credentialSets?:CredentialSet[]}>(),{proxies:()=>[],credentialSets:()=>[]})
const emit=defineEmits<{(e:'update:modelValue',value:ScanConfig):void}>()
function set<K extends keyof ScanConfig>(key:K,value:ScanConfig[K]){emit('update:modelValue',{...props.modelValue,[key]:value})}
const targets=computed({get:()=>props.modelValue.targets.join('\n'),set:(v:string)=>set('targets',v.split(/[\s,]+/).filter(Boolean))})
type NumericKey='rate'|'retry'|'wait'|'threads'|'max_targets'|'http_requests'|'http_per_host'|'http_rps'|'timeout_seconds'|'host_timeout_seconds'|'host_workers'
type NumericField={key:NumericKey;label:string;min:number;cap:string;decimal?:boolean;hint?:string}
const discovery:NumericField[]=[{key:'rate',label:'Discovery rate / second',min:1,cap:'max_rate'},{key:'retry',label:'Discovery retries',min:0,cap:'max_retry'},{key:'wait',label:'Discovery wait (seconds)',min:0,cap:'max_wait'},{key:'threads',label:'Discovery threads',min:1,cap:'max_threads'},{key:'max_targets',label:'Maximum target addresses',min:1,cap:'max_targets',hint:'A guardrail, not a sample size. Larger scopes are rejected, never silently sampled.'}]
const http:NumericField[]=[{key:'http_requests',label:'Concurrent HTTP requests',min:1,cap:'max_http_requests'},{key:'http_per_host',label:'HTTP requests per destination host',min:1,cap:'max_http_per_host'},{key:'http_rps',label:'HTTP requests / second',min:0,cap:'max_http_rps',decimal:true,hint:'Includes redirects. Zero explicitly disables pacing when server policy allows it.'}]
const budgets:NumericField[]=[{key:'timeout_seconds',label:'Whole-job timeout (seconds)',min:.001,cap:'max_timeout_seconds',decimal:true},{key:'host_timeout_seconds',label:'Per-host timeout (seconds)',min:.001,cap:'max_host_timeout_seconds',decimal:true},{key:'host_workers',label:'Concurrent host workers',min:1,cap:'max_host_workers'}]
const routing=[{key:'adapter',label:'Network interface',hint:'Interface inside the runner network namespace.'},{key:'adapter_ip',label:'Interface IPv4 address',hint:'Optional source IPv4 address.'},{key:'router_ip',label:'Next-hop router IPv4 address',hint:'Optional gateway for raw discovery.'},{key:'router_mac',label:'Next-hop router MAC',hint:'The router MAC, not the destination camera MAC.'},{key:'route_target',label:'Route reference IPv4 address',hint:'Optional reference used to resolve the route once per raw batch.'}] as const
function value(f:NumericField){return Number.isFinite(props.modelValue[f.key])?props.modelValue[f.key]:''}
function number(f:NumericField,v:string|number|null){set(f.key,v===''||v===null?Number.NaN:Number(v))}
function rules(f:NumericField){return [(v:unknown)=>v!==''&&v!==null&&Number.isFinite(Number(v))||'Enter a number.',(v:unknown)=>Number(v)>=f.min||`Minimum ${f.min}.`,(v:unknown)=>f.decimal||Number.isInteger(Number(v))||'Use a whole number.',(v:unknown)=>typeof props.policy[f.cap]!=='number'||Number(v)<=(props.policy[f.cap] as number)||`Server limit: ${props.policy[f.cap]}.`]}
const proxyOptions=computed(()=>[{label:'Direct HTTP requests',value:''},...props.proxies.map(p=>({label:`${p.name} · ${p.host}:${p.port}`,value:p.version_id}))])
</script>
<template>
 <div class="configuration-fields">
  <section class="form-section"><h2>Scope and discovery</h2><p class="helper">Enter IP addresses, CIDRs, or inclusive IP_FROM-IP_TO ranges.</p><div class="config-grid">
   <q-input data-testid="targets" v-model="targets" type="textarea" outlined autogrow label="Target IP addresses, CIDRs or ranges" class="span-full" placeholder="192.0.2.10-192.0.2.50" hint="Separate entries with a line break or comma." :rules="[()=>modelValue.targets.length>0||'Add at least one target.']"/>
   <q-select :model-value="modelValue.port_mode" @update:model-value="set('port_mode',$event)" emit-value map-options outlined label="Port selection" :options="[{label:'Camera service ports',value:'camera'},{label:'Comprehensive camera ports',value:'comprehensive'},{label:'Custom ports and ranges',value:'custom'}]"/>
   <q-select :model-value="modelValue.scan_mode" @update:model-value="set('scan_mode',$event)" emit-value map-options outlined label="Discovery method" :options="[{label:'TCP connect · unprivileged',value:'connect'},{label:'Raw + connect · requires raw runner',value:'auto',disable:policy.allow_raw!==true},{label:'SYN · requires raw runner',value:'syn',disable:policy.allow_raw!==true}]" hint="Raw discovery is unavailable unless explicitly enabled on a capable runner."/>
   <q-input v-if="modelValue.port_mode==='custom'" :model-value="modelValue.ports" @update:model-value="set('ports',String($event??''))" outlined label="Custom ports" placeholder="80,443,554,8000-8010" class="span-full" :rules="[v=>!!String(v).trim()||'Enter ports or ranges.']"/>
   <q-input v-for="field in discovery" :key="field.key" :data-testid="field.key" :model-value="value(field)" @update:model-value="number(field,$event)" type="number" :step="field.decimal?'any':1" :min="field.min" :max="typeof policy[field.cap]==='number'?policy[field.cap] as number:undefined" outlined :label="field.label" :hint="field.hint" :rules="rules(field)"/>
  </div></section>
  <section class="form-section"><h2>HTTP routing and budgets</h2><p class="helper">Each job runs in its own process. These HTTP limits cover that scanner process, including redirects and response-body lifetime.</p><div class="config-grid">
   <q-select :model-value="modelValue.proxy_version_id" @update:model-value="set('proxy_version_id',$event)" emit-value map-options outlined label="HTTP / HTTPS proxy profile" :options="proxyOptions" class="span-full" hint="The job pins an immutable proxy version. Authentication details are never sent back to the browser."/>
   <q-input v-for="field in http" :key="field.key" :data-testid="field.key" :model-value="value(field)" @update:model-value="number(field,$event)" type="number" :step="field.decimal?'any':1" :min="field.min" outlined :label="field.label" :hint="field.hint" :rules="rules(field)"/>
  </div><p class="helper q-mt-md">Proxy applies to HTTP/HTTPS requests.</p><a href="/proxies" target="_blank" rel="noopener" class="helper">Manage proxy profiles in a new tab</a></section>
  <section class="form-section"><h2>Execution limits</h2><div class="config-grid"><q-input v-for="field in budgets" :key="field.key" :data-testid="field.key" :model-value="value(field)" @update:model-value="number(field,$event)" type="number" :step="field.decimal?'any':1" :min="field.min" outlined :label="field.label" :rules="rules(field)"/></div></section>
  <section class="form-section"><h2>Checks and capture</h2>
   <q-checkbox :model-value="modelValue.check_credentials" @update:model-value="set('check_credentials',$event)" :disable="policy.allow_credentials!==true" label="Credential checks" color="dark"/><p class="helper q-ml-xl">Use the selected credential set.</p>
   <q-select v-if="modelValue.check_credentials" :model-value="modelValue.credential_set_id" @update:model-value="set('credential_set_id',$event)" emit-value map-options outlined label="Credential set" :options="credentialSets.map(s=>({label:`${s.name} · ${s.entry_count} entries`,value:s.id}))" :rules="[v=>!!v||'Select an imported credential set.']"><template #no-option><q-item><q-item-section>Import a credential set before enabling checks.</q-item-section></q-item></template></q-select>
   <div><q-checkbox :model-value="modelValue.capture" @update:model-value="set('capture',$event)" :disable="policy.allow_capture!==true" label="HTTP still images" color="dark"/><p class="helper q-ml-xl">Save bounded, validated snapshots as private evidence. This is not continuous video recording.</p></div>
   <div><q-checkbox :model-value="modelValue.onvif" @update:model-value="set('onvif',$event)" :disable="policy.allow_onvif!==true" label="ONVIF UDP discovery" color="dark"/><p class="helper q-ml-xl">Discover ONVIF devices over UDP.</p></div>
  </section>
  <section class="form-section"><q-expansion-item label="Advanced routing and diagnostics" caption="Raw-runner network controls; no machine-specific defaults" header-class="q-pa-none" expand-separator><div class="config-grid q-mt-lg"><q-input v-for="field in routing" :key="field.key" :model-value="modelValue[field.key]" @update:model-value="set(field.key,String($event??''))" outlined :label="field.label" :hint="field.hint"/></div><q-checkbox class="q-mt-md" :model-value="modelValue.debug" @update:model-value="set('debug',$event)" label="Scanner debug mode" color="dark"/><p class="helper">The runner still restricts persisted diagnostic output. Proxy and credential values must never appear in logs.</p></q-expansion-item></section>
 </div>
</template>
